"""Apply verified bibliographic and citation-placement decisions."""
from common import ROOT
import re,json
R=ROOT/'revision/review_v5';p=R/'manuscript.md';t=p.read_text(encoding='utf-8')
t=t.replace('BCa intervals, multiyear blocks and score omissions assess concentration in particular years.','BCa intervals (Efron 1987), multiyear blocks and score omissions assess concentration in particular years.')
t=t.replace('In the frozen 2020 test, six domains favour aggregate reconciliation,','Northern forward validation in 2015–2019 reverses the retrospective ordering. In the frozen 2020 test, six domains favour aggregate reconciliation,')
# The mixture-specific reference accompanies the moved experiment, not an uncited main entry.
entry=next(b for b in t.split('\n\n') if b.startswith('Ranjan R, Gneiting T (2010)'))
t=t.replace(entry+'\n\n','')
t=t.replace('Nature, published online 14 October 2026.','Nature 658, 951–957. Published online 14 October 2026.')
p.write_text(t,encoding='utf-8');(R/'supplementary_references.md').write_text('## Supplementary references\n\nReferences shared with the main text are listed in its bibliography. The following source is specific to the probability-combination experiment.\n\n'+entry+'\n',encoding='utf-8')
# Publisher issue contents take precedence over inconsistent registry ordering/pages for Kalnay.
decisions={'date':'2026-10-25','doi_count':35,'non_doi_count':5,'total_references':40,'main_references':39,'supplement_only_references':1,'changes':['Guan et al. 2026: added Crossref-assigned volume 658 and pages 951–957; Nature confirms online publication on 14 October 2026.','Efron 1987: citation added at first main-text BCa use.','Ranjan and Gneiting 2010: moved to supplementary bibliography with the mixture experiment.'],'metadata_exceptions':{'Kalnay 1996':'AMS Volume 77 Issue 3 contents list pages 437–472 and the author order used here. Crossref lists 437–471 and a different placement of Leetmaa/Reynolds; NOAA citation examples also vary. The current publisher issue contents are retained.','Ferro 2014; Reid et al. 2024; Wickramasuriya et al. 2019':'Years follow the journal volume/issue, not earlier online publication dates.'},'non_doi_sources':[{'key':'Bureau undated a','url':'https://s2dprediction.nci.org.au/access-s/reference/hindcast_data.html/','verified':'Official catalogue confirms public research hindcasts without login.'},{'key':'Bureau undated b','url':'https://www.bom.gov.au/resources/learn-and-explore/climate-knowledge-centre/climate-factors/indian-ocean-dipole','verified':'Official page gives August–October peak and rapid decay with monsoon arrival.'},{'key':'ECMWF 2021','url':'https://github.com/ecmwf-lab/climetlab-s2s-ai-challenge','verified':'Official archived package documents hindcast/test roles, dates, members and files.'},{'key':'ECMWF 2026','url':'https://confluence.ecmwf.int/pages/viewpage.action?pageId=639218194','verified':'Pinned documentation revision updated 3 February 2026 describes accumulated-field discontinuity at day 16.'},{'key':'Neubauer and Filzmoser 2024','url':'https://arxiv.org/abs/2407.02367v1','verified':'Explicitly cited v1 preprint of 2 July 2024; later v2 exists. Claim is restricted to temporally aggregated models.'}],'kalnay_publisher_url':'https://journals.ametsoc.org/view/journals/bams/77/3/bams.77.issue-3.xml','scope':'Existence and bibliographic metadata checked for every item. Citation placement reviewed against the stated method, publisher abstracts and accessible original pages; this is not a claim to have independently reproduced every cited study.'}
(R/'reference_metadata/verification_decisions.json').write_text(json.dumps(decisions,ensure_ascii=False,indent=2),encoding='utf-8')
print('Abstract words',len(t.split('## Abstract\n\n')[1].split('\n\n')[0].split()))
